import React, { useState } from 'react';
import { VideoDetailedInfoUI, VideoDownloadStatus, DOWNLOAD_STATE, ProgressBarVariant, OS_TYPE } from '../../interfaces';
import DownloadButton from './DownloadButton';
import ProgressBar from './ProgressBar';
import { useSelector, useDispatch } from 'react-redux';
import '../common/styles/popup.scss';
import '../common/styles/player.scss';
import { VideoMediaManagerUI } from '../../utils/VideoMediaManagerUI';
import { MESSAGE_TYPES, REDUX_ACTIONS } from '../../constants';
import UiUtils from '../../utils/UiUtils';
import sharedUtils from '../../utils/sharedUtils';
import { isRtlEnvironment } from '../../utils/LocaleUtils';

interface VideoCardProps {
  video: VideoDetailedInfoUI;
  downloadStatus?: VideoDownloadStatus; // Use download status from Redux or parent
  onDownloadStart?: (videoId: string) => void;
  onCancelDownload?: (videoId: string) => void;
  onTryAgain?: (videoId: string) => void;
  onDownloadAttempt?: (format: any) => void;
}

const LAST_SELECTED_VIDEO_KEY = 'lastSelectedVideoId';

const VideoCard: React.FC<VideoCardProps> = ({ video, downloadStatus, onDownloadStart, onCancelDownload, onTryAgain, onDownloadAttempt }) => {
  const metadataValues = useSelector((state: any) => state.metaData.metadataValues)
  // Get formats from Redux store metadata
  const metaData = useSelector((state: any) => {
    const provider = Object.keys(state.metaData.metadataValues).find(providerName =>
      state.metaData.metadataValues[providerName][video.videoId]
    );
    return provider
      ? state.metaData.metadataValues[provider][video.videoId]
      : undefined;
  });
  const dispatch = useDispatch();

  const downloadInitiatedVideos = useSelector((state: any) => state.downloadInitiatedVideos.downloadInitiatedVideos);
  // Use download status from props or fallback to idle
   // If no status is provided, treat as 'not started' (TBD: add explicit NOT_STARTED state)
   const status: VideoDownloadStatus = VideoMediaManagerUI.getDownloadStatus(video.videoId, downloadInitiatedVideos);

  const strings = {
    videoDownloader: chrome.i18n.getMessage('appName'),
    showText: sharedUtils.getOSType() === OS_TYPE.WINDOWS ? chrome.i18n.getMessage('showInFolder') : chrome.i18n.getMessage('showInFinder'),
    tryAgain: chrome.i18n.getMessage('tryAgain'),
    downloadComplete: chrome.i18n.getMessage('downloadComplete'),
    downloadFailed: chrome.i18n.getMessage('downloadFailed')
  };

  // Show in folder logic
  const handleShowInFolder = () => {
    chrome.downloads.showDefaultFolder();
    chrome.runtime.sendMessage({ 
      type: MESSAGE_TYPES.SHOW_IN_FOLDER_CLICKED
    });
  };

  const onRetry = (videoId: string) => {
    chrome.runtime.sendMessage({ 
      type: MESSAGE_TYPES.RETRY_CLICKED,  
      payload: { 
        videoId,
        videoAttributes: status.videoAttributes,
        videoProvider: UiUtils.getProviderFromId(videoId, metadataValues)
      },
    });
    onTryAgain && onTryAgain(videoId)
  }

  // Check RTL environment
  const isRtl = isRtlEnvironment();

  return (
    <div className={`video-card${isRtl ? ' rtl' : ''}`}>
      <div
        className="video-thumbnail"
        style={{ backgroundImage: `url(${video.thumbnailURL})` }}
        aria-label={video.title}
      />
      <div className="video-info">
        <div className="video-title">{video.title}</div>
        <div className="video-actions">
          {/* Show DownloadButton only if download has not started or is cancelled */}
          {(video.downloadInitiatedVideosInformation.downloadState === DOWNLOAD_STATE.NOT_STARTED || video.downloadInitiatedVideosInformation.downloadState === DOWNLOAD_STATE.CANCELLED || video.downloadInitiatedVideosInformation.downloadState === DOWNLOAD_STATE.EULA_NOT_ACCEPTED) && (
            <DownloadButton metaData={metaData} onDownloadAttempt={onDownloadAttempt} fromPopover={true} downloadStatus={video.downloadInitiatedVideosInformation}/>
          )}
          {/* Show progress bar only for active downloads with progress less than 100% */}
          {(video.downloadInitiatedVideosInformation.downloadState === DOWNLOAD_STATE.STARTED || video.downloadInitiatedVideosInformation.downloadState === DOWNLOAD_STATE.CANCELLATION_IN_PROGRESS) && (
            <ProgressBar 
              progressPercentage={status.progressPercentage} 
              videoId={video.videoId} 
              videoAttributes={status.videoAttributes} 
              variant={ProgressBarVariant.POPUP}
              status={status}
            />
          )}
          {video.downloadInitiatedVideosInformation.downloadState === DOWNLOAD_STATE.COMPLETED && (
            <div className="download-status-row success">
              <span className="icon-completed" />
              <span className="download-status-text">{strings.downloadComplete}</span>
              <span
                className="show-in-folder-link"
                onClick={handleShowInFolder}
                role="link"
                tabIndex={0}
              >
                {strings.showText}
              </span>
            </div>
          )}
          {UiUtils.isErrorState(video.downloadInitiatedVideosInformation.downloadState) && (
            <div className="download-status-row failed">
              <span className="icon-alert" />
              <span className="download-status-text">{strings.downloadFailed}</span>
              <span
                className="try-again-link"
                onClick={() => onRetry(video.videoId)}
                role="link"
                tabIndex={0}
              >
                {strings.tryAgain}
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default VideoCard;
