/**
 * Interface representing video download metrics for telemetry tracking.
 * These metrics track various counts related to video download operations.
 * 
 * Uses computed property names from VIDEO_DOWNLOAD_METRICS_KEY to ensure
 * automatic synchronization between the constant and interface.
 */
export interface VideoDownloadMetrics {
    /** Count of successfully downloaded videos */
    [VIDEO_DOWNLOAD_METRICS_KEY.DOWNLOADED_VIDEOS_COUNT]: number;
    /** Count of failed video downloads */
    [VIDEO_DOWNLOAD_METRICS_KEY.FAILED_VIDEO_DOWNLOADS_COUNT]: number;
    /** Count of videos that are not supported */
    [VIDEO_DOWNLOAD_METRICS_KEY.NOT_SUPPORTED_VIDEOS_COUNT]: number;
    /** Count of videos that were played */
    [VIDEO_DOWNLOAD_METRICS_KEY.VIDEOS_PLAYED_COUNT]: number;
    /** Count of metadata 403 errors */
    [VIDEO_DOWNLOAD_METRICS_KEY.METADATA_403_ERROR_COUNT]: number;
}

/**
 * Interface representing the dynamic telemetry parameters sent with heartbeat pings.
 * These parameters contain various counts and theme information that are tracked
 * and reset after each heartbeat interval.
 */
export interface HeartbeatDynamicTelemetryParams extends VideoDownloadMetrics {
    /** Current browser theme (light/dark) */
    browser_theme: string;
    /** Current extension theme (light/dark) */
    extension_theme: string;
}

