import { OS_TYPE } from '../interfaces';

class SharedUtils {
    /**
     * Determines the operating system type based on the user's browser application version.
     * 
     * @returns {OS_TYPE} The type of operating system detected. Possible values are:
     * - `OS_TYPE.WINDOWS` for Windows operating systems.
     * - `OS_TYPE.MAC` for macOS operating systems.
     */
    getOSType(): OS_TYPE {
        if (navigator.appVersion.toLowerCase().indexOf("win")!=-1) {
          return OS_TYPE.WINDOWS;
        }
        if (navigator.appVersion.toLowerCase().indexOf("mac")!=-1){
            return OS_TYPE.MAC;
        }
    };
    
}

const sharedUtils = new SharedUtils();
export default sharedUtils;