import { METADATA_NAME_SEPERATOR } from "../constants";
import { DOWNLOAD_STATE, DownloadInitiatedVideos, DownloadInitiatedVideosInformation, videoAttributes, VideoDetailedInfoUI, VideoDownloadStatus, VideoMetaData } from "../interfaces";

class VideoMediaManagerUI {

    /**
     * Generates a list of detailed video information objects based on metadata and download statuses.
     *
     * @param metadataValues - An object containing metadata for videos, where the keys are video IDs and the values are metadata objects.
     * @param downloadInitiatedVideos - An object mapping video IDs to their download statuses. Each key is a video ID, and the value is an array of statuses.
     * @returns An array of `VideoDetailedInfoUI` objects containing detailed information about each video, including metadata and download status.
     */
    static getVideoList(metadataValues, downloadInitiatedVideos): VideoDetailedInfoUI[] {
      const videoList = [];
      // Use metadataValues as-is (already flattened)
      Object.entries(downloadInitiatedVideos).forEach(([key, values]: [string, any]) => {
        values.forEach(value => {
          const metadata = metadataValues[key];
          const baseObject = {
            videoId: key,
            title: metadata?.videoDetails?.title || '',
            thumbnailURL: metadata?.videoDetails?.thumbnail || '',
            downloadInitiatedVideosInformation: value,
            formats: metadata?.formats || { videoFormats: [], audioFormats: [] },
          };
          videoList.push(baseObject)
        });
      });
      return videoList;
    }

    /**
     * Determines the download status of a video based on its metadata and the list of initiated downloads.
     *
     * @param video - The detailed information of the video, including its unique video ID.
     * @param downloadInitiatedVideos - A mapping of video IDs to their respective download statuses.
     * @returns An object representing the download status of the video, including its ID, download state, and progress percentage.
     *
     * The method handles two cases:
     * 1. If the video ID contains a resolution identifier (`METADATA_RESOLUTION_IDENTIFIER`), it extracts the resolution and video ID,
     *    then finds the corresponding download status for that resolution.
     * 2. If the video ID does not contain a resolution identifier, it checks the list of download statuses for the video ID and
     *    returns the first status that is not marked as completed. If no such status exists, it returns a default status indicating
     *    that the download has not started.
     */
    static getDownloadStatus(videoId: string, downloadInitiatedVideos: DownloadInitiatedVideos): VideoDownloadStatus{
        if (videoId.includes(METADATA_NAME_SEPERATOR)) {
          const attributes = videoId.split(METADATA_NAME_SEPERATOR);
          const attribute: videoAttributes = {
            [attributes[1]]: [attributes[2]]
          }
          const [attributeKey, attributeValue] = Object.entries(attribute)[0];
          const videoID = videoId.split(METADATA_NAME_SEPERATOR)[0];
          const result =  downloadInitiatedVideos[videoID].find(item => item.videoAttributes[attributeKey] === Number(attributeValue));
          return {
            videoId: videoID,
            ...result
          }
        }
        
        const downloadStatuses = downloadInitiatedVideos[videoId];
        if (!downloadStatuses) {
          return {
            videoId,
            downloadState: undefined, // undefined means not started
            progressPercentage: 0
          }
        }
        const result = downloadStatuses.find(item => item.downloadState !== DOWNLOAD_STATE.COMPLETED);
        if (!result) {
          return {
            videoId,
            downloadState: undefined,
            progressPercentage: 0
          }
        }
        return {
            videoId,
            ...result
        };
      }

      /**
       * Helper to get a single status for a given VideoMetaData.
       * Returns { videoDetailedInfo, status }.
       */
      static getSingleVideoStatus(metaData: VideoMetaData, downloadInitiatedVideos: DownloadInitiatedVideos) {
        if (!metaData || !metaData.videoDetails) return { status: undefined };
        const status = this.getDownloadStatus(metaData.videoDetails.videoId, downloadInitiatedVideos);
        return { status };
    }
}
export { VideoMediaManagerUI };
