import React, { useEffect } from 'react';
import '../common/styles/popup.scss';
import { MESSAGE_TYPES } from '../../constants';
import TelemetryUtils from '../../telemetry/telemetryUtils';
import { TELEMETRY_EVENT_TYPES } from '../../telemetry/telemetryConstants';

const VideoNotFound: React.FC = () => {
  const strings = {
    noVideosTitle: chrome.i18n.getMessage('noVideosFound'),
    noVideosDesc: chrome.i18n.getMessage('noVideosFoundDesc')
  };

  // Send telemetry when VideoNotFound component loads
  useEffect(() => {
    try {
      TelemetryUtils.sendTelemetryMessageForUI(TELEMETRY_EVENT_TYPES.VIDEO_NOT_FOUND_PAGEVIEW);
    } catch (error) {
      // Silently handle telemetry errors to prevent component crashes
      console.warn('Telemetry failed:', error);
    }
  }, []);

  return (
    <div className="video-not-found-container" data-testid="video-not-found">
      <div className="video-not-found-graphic-bg" />
      <div className="video-not-found-text">
        <div className="vnf-title">{strings.noVideosTitle}</div>
        <div className="vnf-desc">{strings.noVideosDesc}</div>
      </div>
    </div>
  );
};

export default VideoNotFound;
