import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { useSelector } from 'react-redux';

// Context value type: { [videoId: string]: { progressPercentage, downloadState } }
export const DownloadProgressContext = createContext<any>({});

export const DownloadProgressProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Subscribe to Redux only once here
  const downloadInitiatedVideos = useSelector((state: any) => state.downloadInitiatedVideos.downloadInitiatedVideos);
  const [progressMap, setProgressMap] = useState(downloadInitiatedVideos);

  useEffect(() => {
    setProgressMap(downloadInitiatedVideos);
  }, [downloadInitiatedVideos]);

  return (
    <DownloadProgressContext.Provider value={progressMap}>
      {children}
    </DownloadProgressContext.Provider>
  );
};

export const useDownloadProgress = (videoId: string) => {
  const progressMap = useContext(DownloadProgressContext);
  // Defensive: ensure progressMap is an object and has downloadInitiatedVideos
  if (!progressMap || typeof progressMap !== 'object') return undefined;
  // If progressMap is undefined, return undefined
  if (!progressMap) return undefined;
  // If progressMap is the nested shape, use it
  if (progressMap.downloadInitiatedVideos) {
    return videoId ? progressMap.downloadInitiatedVideos[videoId] : undefined;
  }
  // If progressMap is flat, use it directly
  return videoId ? progressMap[videoId] : undefined;
};
