import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import ReactDOM from 'react-dom/client';
import { Provider, useDispatch, useSelector } from 'react-redux';
import { Store } from 'webext-redux';
import DownloadList from './DownloadList';
import VideoNotFound from './VideoNotFound';
import InfoPopup from './InfoPopup';
import { INFORMATION_LINK, MESSAGE_TYPES } from '../../constants';
import { TELEMETRY_LABEL, TELEMETRY_EVENT_TYPES, TELEMETRY_ORIGIN } from '../../telemetry/telemetryConstants';
import TelemetryUtils from '../../telemetry/telemetryUtils';
import '../common/styles/popup.scss';
import { DownloadProgressProvider } from './DownloadProgressContext';
import { VideoMediaManagerUI } from '../../utils/VideoMediaManagerUI';
import helperUtils from '../../utils/HelperUtils';
import UiUtils from '../../utils/UiUtils';
import { DOWNLOAD_STATE } from '../../interfaces';

// Popup: Main container for the extension popup UI
const Popup: React.FC = () => {
  // Get all metadata from Redux store
  const { metadataValues } = useSelector((state: { metaData: { metadataValues: any } }) => state.metaData);
  // Flatten all videos from all providers
  const videoList = Object.values(metadataValues).flatMap(providerVideos => Object.values(providerVideos));

  const metaData = UiUtils.getMetadataObject(metadataValues);
  const downloadInitiatedVideos = useSelector((state: any) => state.downloadInitiatedVideos.downloadInitiatedVideos) || {};
  const videoListForUI = VideoMediaManagerUI.getVideoList(metaData, downloadInitiatedVideos);
  
  // State for current tab hostname
  const [currentHostname, setCurrentHostname] = useState<string>('');

  // Fetch hostname only once on mount
  useEffect(() => {
    const fetchHostname = async () => {
        const hostname = await helperUtils.getCurrentTabHostname();
        setCurrentHostname(hostname);
    };
    fetchHostname();
  }, []);

  // Compute filtered video list directly in render (no useEffect needed)
  const filteredVideoListForUI = helperUtils.filterVideosForHostname(videoListForUI, currentHostname);

  const dispatch = useDispatch();
  const eulaAcceptanceDetails = useSelector((state: any) => state.eulaAcceptanceDetails);
  const eulaAccepted = eulaAcceptanceDetails.isEulaAccepted;
  const [showNotFound, setShowNotFound] = useState(false); // Reserved for future use
  const containerRef = useRef<HTMLDivElement>(null);
  const { currentTheme } = useSelector((state: any) => state.UIConfigurations);
  const prevPopupHeight = useRef(null);
  const [showInfoPopup, setShowInfoPopup] = useState(false);
  const infoPopupRef = useRef<HTMLDivElement>(null);
  
  // Send pageview telemetry when popup loads
  useEffect(() => {
    filteredVideoListForUI.length > 0 && TelemetryUtils.sendTelemetryMessageForUI(TELEMETRY_EVENT_TYPES.POPOVER_PAGEVIEW);
  }, []);
  
  // Post height to background for dynamic resizing
  useEffect(() => {
    document.documentElement.setAttribute('data-gen-theme', currentTheme);
    const postHeight = () => {
      if (containerRef.current && prevPopupHeight.current !== containerRef.current.offsetHeight) {
        prevPopupHeight.current = containerRef.current.offsetHeight;
        chrome.runtime.sendMessage({ type: MESSAGE_TYPES.SET_IFRAME_POPUP_HEIGHT, height: containerRef.current.offsetHeight });
      }
    };
    postHeight();
    // Use ResizeObserver for robust height tracking
    const observer = new window.ResizeObserver(postHeight);
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  // Handle InfoPopup positioning and height expansion similar to DownloadButton's FormatsList pattern
  useLayoutEffect(() => {
    if (!showInfoPopup || !containerRef.current || !infoPopupRef.current) return;
    
    const containerElement = containerRef.current;
    const infoPopupElement = infoPopupRef.current;
    const containerRect = containerElement.getBoundingClientRect();
    const infoPopupHeight = infoPopupElement.offsetHeight;
    
    // Calculate if InfoPopup extends beyond current container height
    const containerBottom = containerRect.bottom;
    const infoPopupBottom = containerRect.top + infoPopupHeight + 80; // 80px for header + margins
    
    if (infoPopupBottom > containerBottom) {
      // InfoPopup extends beyond container, increase iframe height
      const additionalHeight = infoPopupBottom - containerBottom + 20; // 20px padding
      const newHeight = containerElement.offsetHeight + additionalHeight;
      
      // Ensure container background extends to fill the expanded area
      containerElement.style.minHeight = `${newHeight}px`;
      containerElement.style.height = 'auto';
      
      chrome.runtime.sendMessage({ 
        type: MESSAGE_TYPES.SET_IFRAME_POPUP_HEIGHT, 
        height: newHeight 
      });
    }
    
    // reset container styling when InfoPopup is hidden
    return () => {
      if (containerRef.current) {
        containerRef.current.style.minHeight = '';
        containerRef.current.style.height = 'auto';
      }
    };
  }, [showInfoPopup]);

  // Download attempt handler (called from DownloadButton)
  const handleDownloadAttempt = (format: any) => {
    // Note: Download click telemetry is now handled in DownloadButton component
    
    if (!eulaAccepted) {
      // EULA popup is handled globally via content script, do not show here
      return;
    } else {
      dispatch({
        type: 'VIDEO_DOWNLOAD_STARTED',
        payload: { 
          format,
          downloadSource: TELEMETRY_LABEL.MAIN_MENU // Since this is from popup/popover
        }
      });
    }
  };

  const strings = {
    videoDownloader: chrome.i18n.getMessage('appName'),
    moreInformation: chrome.i18n.getMessage('moreInformation'),
  };

  // Handle info icon click with telemetry - toggle InfoPopup on/off
  const handleInfoIconClick = () => {
    setShowInfoPopup(!showInfoPopup);
    TelemetryUtils.sendTelemetryMessageForUI(TELEMETRY_EVENT_TYPES.INFO_CLICK, { origin: TELEMETRY_ORIGIN.POPUP });
  };

  // Hide InfoPopup when clicking outside (but not on the info icon itself)
  useEffect(() => {
    if (!showInfoPopup) return;
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      const isInfoIcon = (target as Element)?.closest?.('.info-icon');
      const isInsideInfoPopup = infoPopupRef.current && infoPopupRef.current.contains(target);
      
      if (!isInsideInfoPopup && !isInfoIcon) {
        setShowInfoPopup(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showInfoPopup]);

  return (
    <div className="popup-container" ref={containerRef}>
      {/* Header with logo, title, and info icon */}
      <div className="popup-header">
        <span className="logo" />
        <span className="popup-title">{strings.videoDownloader}</span>
        <a
          className="info-icon"
          target="_blank"
          rel="noopener noreferrer"
          title={strings.moreInformation}
          aria-label={strings.moreInformation}
          onClick={handleInfoIconClick}
        />
      </div>
      {/* InfoPopup positioned absolutely to overlay content */}
      {showInfoPopup && (
        <div className="info-popup-wrapper">
          <div className="info-popup-popup-context">
            <InfoPopup ref={infoPopupRef} onMouseEnter={() => setShowInfoPopup(true)} />
          </div>
        </div>
      )}
      {/* Conditionally render DownloadList or VideoNotFound */}
      {showNotFound ? (
        <VideoNotFound />
      ) : (
        filteredVideoListForUI.length > 0 ? (
          <DownloadList videoList={filteredVideoListForUI} onDownloadAttempt={handleDownloadAttempt} />
        ) : (
          <VideoNotFound />
        )
      )}
    </div>
  );
};

// Mount the popup with the proxy Redux store
const initApp = async () => {
  const proxyStore = new Store();
  await proxyStore.ready();
  const root = ReactDOM.createRoot(document.getElementById('root'));
  root.render(
    <Provider store={proxyStore}>
      <DownloadProgressProvider>
        <Popup />
      </DownloadProgressProvider>
    </Provider>,
  );

  // Add visibilitychange listener in the UI (top-level of popup)
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      // Send a message to the content script to close the iframe
      chrome.runtime.sendMessage({ type: MESSAGE_TYPES.HIDE_IFRAME_POPUP });
    }
  });
};

initApp();

export { Popup };