import React from 'react';
import VideoCard from './VideoCard';
import { VideoDetailedInfoUI } from '../../interfaces';
import '../common/styles/popup.scss';

interface DownloadListProps {
  videoList: VideoDetailedInfoUI[];
  onDownloadAttempt: (format: any) => void;
}

const DownloadList: React.FC<DownloadListProps> = ({ videoList, onDownloadAttempt }) => {
  return (
    <div className="download-list">
      {videoList.map(video => (
        <div key={video.videoId} className="video-list-item-with-download">
          <VideoCard video={video} onDownloadAttempt={onDownloadAttempt} />
        </div>
      ))}
    </div>
  );
};

export default DownloadList;
