import React, { useEffect } from 'react';
import Icon from './common/Icon'; // Adjust the import path according to your project structure
import { DOWNLOAD_STATE, VideoDownloadStatus, ProgressBarVariant } from '../../interfaces';
import { useDispatch, useSelector } from 'react-redux';
import '../common/styles/player.scss';
import { REDUX_ACTIONS, MESSAGE_TYPES, OFFSCREEN_MESSAGE_TYPES, PROGRESS_BAR_STAGES } from '../../constants';
import { VideoMediaManagerUI } from '../../utils/VideoMediaManagerUI';
import TelemetryUtils from '../../telemetry/telemetryUtils';
import { TELEMETRY_EVENT_TYPES, TELEMETRY_ORIGIN } from '../../telemetry/telemetryConstants';

interface ProgressBarProps {
  progressPercentage: number;
  videoId: string; 
  variant: ProgressBarVariant; // Required for UI styling and icon selection
  videoAttributes: any; // Required for uniquely identifying the specific download entry when multiple downloads exist for the same video with different formats or qualities
  status: VideoDownloadStatus;
}

const ProgressBar: React.FC<ProgressBarProps> = ({ progressPercentage, videoId, variant, videoAttributes, status}) => {
  const downloadStatus = status;
  const [showPercent, setShowPercent] = React.useState(false);
  const isCancellationInProgress = downloadStatus.downloadState === DOWNLOAD_STATE.CANCELLATION_IN_PROGRESS;
  const [isCancelling, setIsCancelling] = React.useState(isCancellationInProgress);
  const dispatch = useDispatch();
  const { currentTheme } = useSelector((state: any) => state.UIConfigurations);

  const shouldShowPercent = showPercent;
  const isFromPopover = variant === ProgressBarVariant.POPUP;
  const strings = {
    cancellingText: chrome.i18n.getMessage('cancellingText'),
    cancelDownloadText: chrome.i18n.getMessage('cancelDownloadText'),
    queued: chrome.i18n.getMessage('queued')
  };

  const handleCancel = () => {
    if (!videoId || isCancelling || downloadStatus.progressPercentage === 0) return;
    
    // Set cancelling state to disable button
    setIsCancelling(true);
    
    // Send telemetry for cancel button click based on context
    const origin = isFromPopover ? TELEMETRY_ORIGIN.POPUP : TELEMETRY_ORIGIN.IN_VIDEO;
    TelemetryUtils.sendTelemetryMessageForUI(TELEMETRY_EVENT_TYPES.CANCEL_CLICK, { origin });
    
    // Update the download state in Redux - the middleware will handle sending the message to the background
    chrome.runtime.sendMessage({
      type: MESSAGE_TYPES.CANCEL_CLICKED,
      payload: {
        videoId,
        downloadState: DOWNLOAD_STATE.CANCELLATION_IN_PROGRESS,
        // Pass videoAttributes to ensure we update the correct item for this video
        videoAttributes
      }
    });
  };

  // Get the correct tooltip SVG URL for player UI
  const tooltipSvgUrl = chrome.runtime.getURL(`/assets/images/${currentTheme}/tooltip.svg`);

  // Show carousel bar if progress >= threshold from constants
  const showCarousel = progressPercentage >= PROGRESS_BAR_STAGES.operations.FETCH_OPERATION.maxPercentage;

  return (
    <div
      className={`progress-row${variant ? ` progress-row-${variant}` : ''}`}
      style={{ position: 'relative', width: '100%' }}
      data-testid="progress-bar"
      data-progress={progressPercentage}
    >
      {/* Tooltip: Show on hover for both popup and player, only if below carousel threshold */}
      {shouldShowPercent && !showCarousel && (
        variant === ProgressBarVariant.PLAYER ? (
          <div className="progress-percentage-indicator" style={{ left: `${progressPercentage}%` }}>
            <img
              src={tooltipSvgUrl}
              alt="progress-tooltip"
              className="progress-tooltip-img"
            />
            <span className="progress-percentage-value">
              {progressPercentage}%
            </span>
          </div>
        ) : (
          <div className="progress-percentage-indicator" style={{ left: `${progressPercentage}%` }}>
            <span className="progress-percentage-value">
              {progressPercentage}%
            </span>
          </div>
        )
      )}
      <div className="progress-bar-bg"
        onMouseEnter={() => setShowPercent(true)}
        onMouseLeave={() => setShowPercent(false)}
      >
        {/* Only show progress fill when not showing carousel */}
        {!showCarousel && (
          <div
            className="progress-bar-fill"
            style={{ width: `${progressPercentage}%` }}
          />
        )}
        {/* Carousel loading bar when progress >= threshold */}
        {showCarousel && (
          <div className="progress-bar-carousel" />
        )}
      </div>
      {(isFromPopover && downloadStatus.progressPercentage === 0) && <div className='queued-text'>{strings['queued']}</div>}
      <button
        className={`progress-cancel-btn ${(isCancelling || downloadStatus.progressPercentage === 0)  ? 'disabled' : ''}`}
        onClick={handleCancel}
        disabled={isCancelling}
        aria-label="Cancel download"
        title={isCancelling ? strings.cancellingText : strings.cancelDownloadText}
      >
        <Icon iconUrl={`/assets/images/${currentTheme}/cross.svg`} className={`icon-cross ${(isCancelling || downloadStatus.progressPercentage === 0)  ? 'disabled' : ''}`} /> 
      </button>
    </div>
  );
};

export default ProgressBar;
